SELECT ?ahu ?zone ?point WHERE {
  ?ahu rdf:type brick:AirHandlingUnit ; brick:hasIdentifier "AHU02" .
}

SELECT DISTINCT ?b WHERE {
  ?b brick:type brick:AirHandlingUnit
} LIMIT 20

